class Solution {
public:
    int search(vector<int>& nums, int target) {
        int length = nums.size();
        int l = 0 , h = length-1;
        while(l<=h){
            int mid = (l+h)/2;
            if(nums[mid] == target){return mid;}
            if(nums[mid]>target){
                h = mid - 1;
            }
            else{
                l = mid + 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {
        int n = nums.size();
        int index = INT_MIN;
        int start = 0 , end = n-1;
        while(start <= end){
            int mid = (start+end)/2;
            if(nums[mid] == target){
                return mid;
            }
            else if(nums[mid] > target){
                index = mid;
                end = mid - 1;
            }
            else if(nums[mid] < target){
                index = mid + 1;
                start = mid + 1;
            }
        }
        return index;
    }
};

class Solution {
public:
    vector<int> searchRange(vector<int>& nums, int target) {
        vector<int> v(2 , -1);
        int n = nums.size();
        int start = 0 , end = n-1;

        while(start <= end){
            int mid = (start + end) / 2;
            if(nums[mid] == target){
                v[0] = mid;
                end = mid - 1;
            }
            else if(nums[mid] > target){
                end = mid - 1;
            }
            else if(nums[mid] < target){
                start = mid + 1;
            }
        }

        start = 0;
        end = n-1;

        while(start <= end){
            int mid = (start + end) / 2;
            if(nums[mid] == target){
                v[1] = mid;
                start = mid + 1;
            }
            else if(nums[mid] > target){
                end = mid - 1;
            }
            else if(nums[mid] < target){
                start = mid + 1;
            }
        }
        return v;
    }
};

class Solution {
public:
    int findPeakElement(vector<int>& nums) {
        int n = nums.size();
        int start = 1 , end = n-2;
        if(n == 1){
            return 0;
        }
        if(nums[0] > nums[1]){
            return 0;
        }
        if(nums[n-1] > nums[n-2]){
            return n-1;
        }

        while(start <= end){
            int mid = (start + end) / 2;

            if(nums[mid] > nums[mid-1] && nums[mid] > nums[mid+1]){
                return mid;
            }
            if(nums[mid-1] > nums[mid]){
                end = mid - 1;
            }
            else{
                start = mid + 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int singleNonDuplicate(vector<int>& nums) {
        int n = nums.size();
        int start = 1 , end = n-2;

        if(n == 1){
            return nums[0];
        }
        if(nums[0] != nums[1]){
            return nums[0];
        }
        if(nums[n-2] != nums[n-1]){
            return nums[n-1];
        }

        while(start <= end){
            int mid = (start + end) / 2;

            if(nums[mid-1] != nums[mid] && nums[mid+1] != nums[mid]){
                return nums[mid];
            }
            if(nums[mid] == nums[mid-1]){
                mid = mid-1;
            }
            if(mid % 2 == 0){
                start = start + 2;
            }
            else{
                end = end - 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int mySqrt(int x) {
        int start = 1 , end = x , ans = 0;

        while(start <= end){
            int mid = start + (end - start) / 2;

            if(mid <= (x/mid)){
                ans = mid;
                start = mid + 1;
            }
            else{
                end = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool isPerfectSquare(int num) {
        long long start = 1 , end = num;

        while(start <= end){
            long long mid = start + (end - start)/2;

            if(mid == num/mid && num % mid == 0){
                return true;
            }
            else if(mid >= (num/mid)){
                end = mid - 1;
            }
            else{
                start = mid + 1;
            }
        }
        return false;
    }
};

