/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int maxDepth(TreeNode* root) {
        if(root == nullptr){
            return 0;
        }

        int ld = maxDepth(root->left);
        int rd = maxDepth(root->right);

        int depth = max(ld , rd) + 1;

        return depth;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
vector<int> prerder(TreeNode* root , vector<int> v){
        TreeNode* curr = root;
        stack<TreeNode*> st;
        while(curr != nullptr || st.size() > 0){
            if(curr != nullptr){
                v.push_back(curr->val);
                st.push(curr);
                curr = curr -> left;
            }
            else{
                curr = st.top();
                st.pop();
                curr = curr -> right;
            }
        }
        return v;
    }
    vector<int> preorderTraversal(TreeNode* root) {
        vector<int> v , x;
        x = prerder(root , v);

        return x;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> inorder(TreeNode* root , vector<int> v){
        TreeNode* curr = root;
        stack<TreeNode*> st;
        while(curr != nullptr || st.size() > 0){
            if(curr != nullptr){
                st.push(curr);
                curr = curr -> left;
            }
            else{
                curr = st.top();
                st.pop();
                v.push_back(curr->val);
                curr = curr -> right;
