class Solution {
public:
    vector<vector<int>> verticalTraversal(TreeNode* root) {
        queue<pair<TreeNode* , int>> q;
        unordered_map<int , vector<pair<int , int>>> um;
        vector<vector<int>> v1;
        int cmax = 0 , cmin = 0 , row = 0;
