    }

    void recoverTree(TreeNode* root) {
        vector<TreeNode*> v;
        TreeNode* f = nullptr;
        TreeNode* s = nullptr;
        int count = 0;

        inOrder(root , v);

        for(int i = 0 ; i < v.size() - 1 ; ++i){
            if(v[i]->val > v[i+1]->val){
                count++;

                if(count == 1){
                    f = v[i];
                    s = v[i+1];
                }
                if(count == 2){
                    s = v[i+1];
                }
            }
        }

        if(f != nullptr && s != nullptr){
            swap(f->val , s->val);
        }
    }
};

