    }
};

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        deque<int> dq;
        vector<int> v;

        for(int i = 0 ; i < k ; ++i){
            while(dq.size() > 0 && dq.back() < nums[i]){
                dq.pop_back();
            }

            dq.push_back(nums[i]);
        }

        if(dq.size() > 0){
            v.push_back(dq.front());
        }

        int s = 1 , e = k;

        while(e < nums.size()){
            if(nums[s-1] == dq.front()){
                dq.pop_front();
            }

            while(dq.size() > 0 && dq.back() < nums[e]){
                dq.pop_back();
            }

            dq.push_back(nums[e]);

            if(dq.size() > 0){
                v.push_back(dq.front());
            }

            s++;
            e++;
        }

        return v;
    }
};

class FreqStack {
public:
    unordered_map<int , stack<int>> fs;
    unordered_map<int , int> um;

    FreqStack() {

    }

    void push(int val) {
        um[val]++;
        int f = um[val];

        if(fs.find(f) == fs.end()){
            stack<int> s;
            fs[f] = s;
        }

        fs[f].push(val);
    }

    int pop() {
        int f = fs.size();
        int elem = fs[f].top();
        fs[f].pop();

        if(fs[f].size() == 0){
            fs.erase(f);
        }

        um[elem]--;
        return elem;
    }
};

