        return area;
    } 

    int maximalSquare(vector<vector<char>>& matrix) {
        int n = matrix.size();
        int m = matrix[0].size();

        int area = 0;
        vector<int> heights(m , 0);

        for(int i = 0 ; i < n ; ++i){
            for(int j = 0 ; j < m ; ++j){
                if(matrix[i][j] == '1'){
                    heights[j]++;
                }
                else{
                    heights[j] = 0;
                }
            }

            area = max(area , squareArea(heights));
        }

        return area;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseList(ListNode* head){
        ListNode* rh = nullptr;
        ListNode* t = head;

        while(head != nullptr){
            head = head->next;
            t->next = rh;
            rh = t;
            t = head;
        }

        return rh;
    }

    vector<int> nextLargerNodes(ListNode* head) {
        vector<int> v;
        stack<int> st;

        head = reverseList(head);
        ListNode* t = head;

        while(t != nullptr){
            while(st.size() > 0 && st.top() <= t->val){
                st.pop();
            }

            if(st.size() > 0){
                v.push_back(st.top());
            }
            else{
                v.push_back(0);
            }

            st.push(t->val);

            t = t->next;
        }

        reverse(v.begin() , v.end());

        return v;
    }
};

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> v(n , 0);
        stack<int> st;

        for(int i = n-1 ; i >= 0 ; --i){
            while(st.size() > 0 && temperatures[st.top()] <= temperatures[i]){
                st.pop();
            }

            if(st.size() > 0){
                v[i] = abs(i - st.top());
            }

            st.push(i);
        }

        return v;
    }
};

class Solution {
public:
    bool isLowerCase(char ch){
        return ch >= 'a' && ch <= 'z';
    }

    bool isUpperCase(char ch){
        return ch >= 'A' && ch <= 'Z';
    }

    string makeGood(string s) {
        stack<char> st;

        for(int i = 0 ; i < s.size() ; ++i){
            if(st.size() != 0 && tolower(st.top()) == tolower(s[i]) && ((isLowerCase(s[i]) && isUpperCase(st.top())) || (isLowerCase(st.top()) && isUpperCase(s[i])))){
                st.pop();
            }
            else{
                st.push(s[i]);
            }
        }

        string ans = "";
        while(st.size() > 0){
            char ch = st.top();
            ans += ch;

            st.pop();
        }

        reverse(ans.begin() , ans.end());

        return ans;
    }
};

class Solution {
public:
    string removeStars(string s) {
        stack<int> st;
        string ans = "";

        for(int i = 0 ; i < s.size() ; ++i){
            if(s[i] == '*' && st.size() > 0){
                st.pop();
            }

            if(s[i] != '*'){
                st.push(s[i]);
            }
        }

        while(st.size() > 0){
            char ch = st.top();
            ans += ch;
            st.pop();
        }

        reverse(ans.begin() , ans.end());

        return ans;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* searchBST(TreeNode* root, int val) {
        TreeNode* t = root;

        if(root == nullptr){
            return nullptr;
        }

        while(t != nullptr){
            if(t->val == val){
                return t;
            }
            else if(t->val > val){
                t = t->left;
            }
            else{
                t = t->right;
            }
        }

        return nullptr;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    void inOrder(TreeNode* root , vector<int> &v){
        if(root == nullptr){
            return;
        }

        inOrder(root->left , v);
        v.push_back(root->val);
        inOrder(root->right , v);
    }

    int kthSmallest(TreeNode* root, int k) {
        vector<int> v;

        inOrder(root , v);

        return v[k-1];
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int rangeSumBST(TreeNode* root, int low, int high) {
        if(root == nullptr){
            return 0;
        }

        if(root->val < low){
            return rangeSumBST(root->right , low , high);
        }

        if(root->val > high){
            return rangeSumBST(root->left , low , high);
        }

        return root->val +
                rangeSumBST(root->left , low , high) +
                rangeSumBST(root->right , low , high);
    }
};

class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        int n1 = nums1.size();
        int n2 = nums2.size();

        vector<int> v(n1 , -1);
        unordered_map<int , int> um;
        stack<int> st;

        for(int i = n2-1 ; i >= 0 ; --i){
            while(st.size() > 0 && st.top() <= nums2[i]){
                st.pop();
            }

            if(st.size() > 0){
                um[nums2[i]] = st.top();
            }

            st.push(nums2[i]);
        }

        for(int i = 0 ; i < n1 ; ++i){
            if(um.find(nums1[i]) != um.end()){
                v[i] = um[nums1[i]];
            }
        }

        return v;
    }
};

class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        priority_queue<int , vector<int> , greater<int>> pq(nums.begin() , nums.end());
        int n = pq.size();

        for(int i = 1 ; i <= n-k ; ++i){
            pq.pop();
        }

        return pq.top();
    }
};
